package ch.bbw.zork;import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.stream.Collectors;/** * A country on the map. * Each country knows its neighboring countries and items in them. * * Uses the template of Michael Kolling and Rinaldo Lanza. * * @author Git-Koy */public class Room {	private String country;	private String description;	private HashMap<String, Room> neighbours;	private ArrayList<Item> items;	/**	 * Creates a country.	 * @param country the id of the country	 * @param description the readable name of the country	 */	public Room(String country, String description) {		this.country = country;		this.description = description;		this.neighbours = new HashMap<>();		this.items = new ArrayList<>();	}	/**	 * Adds a neighbour to a country. This neighbour automatically gets this country as its neighbour as well.	 * @param neighbour the neighbouring country	 */	public void addNeighbour(Room neighbour) {		neighbours.put(neighbour.getCountry(), neighbour);		neighbour.neighbours.put(this.country, this);	}	/**	 * Places an item in the country.	 * @param item the item to add	 */	public void addItem(Item item) {		this.items.add(item);	}	/**	 * Removes an item from the country.	 * @param item the item to remove	 */	public void removeItem(Item item) {		this.items.remove(item);	}	/**	 * Returns the short description of the country.	 * @return the description	 */	public String shortDescription() {		return description;	}	/**	 * Returns the id of the country.	 * @return the id	 */	public String getCountry() {		return country;	}	/**	 * Returns the readable name of the country.	 * @return the description	 */	public String getDescription() {		return description;	}	/**	 * Builds the full description that shows when a player enters a country.	 * @return the long description	 */	public String longDescription() {		StringBuilder stringBuilder = new StringBuilder("You are in " + description + itemString() + ".\n");		stringBuilder.append(exitString());		return stringBuilder.toString();	}	/**	 * Lists all neighbouring countries.	 * @return	 */	private String exitString() {		return "Neighbours: " + String.join(" ", neighbours.keySet());	}	/**	 * Builds a readable sentence that lists all items in a country.	 * @return the items as text	 */	public String itemString() {		if (items.isEmpty()) {			return " which has no item";		} else if (items.size() == 1) {			return " which has "+ items.get(0).getName();		} else {			String itemStorage = " which has the items ";			for(int i = 0; i < items.size(); i++) {				itemStorage += items.get(i).getName();				if (i == items.size() - 1) {					itemStorage += "";				} else if (i == items.size() - 2) {					itemStorage += " and ";				} else {					itemStorage += ", ";				}			}			return itemStorage;		}	}	/**	 * Returns the neighbouring country with the given id.	 *	 * @param country the id of the country to travel to	 * @return the neighbouring country, or null if it is not a neighbour	 */	public Room nextRoom(String country) {		return neighbours.get(country);	}	/**	 * Returns the list of items in this country.	 * @return the items in this country	 */	public ArrayList<Item> getItems() {		return items;	}}